namespace WhatsBiz.Api.Middleware; public sealed class SecurityHeadersMiddleware(RequestDelegate next, IHostEnvironment environment) { public async Task InvokeAsync(HttpContext context) { context.Response.OnStarting(() => { var h = context.Response.Headers; h.TryAdd("X-Content-Type-Options", "nosniff"); h.TryAdd("X-Frame-Options", "DENY"); h.TryAdd("Referrer-Policy", "strict-origin-when-cross-origin"); h.TryAdd("Permissions-Policy", "camera=(), microphone=(), geolocation=()"); if (!environment.IsDevelopment() || !context.Request.Path.StartsWithSegments("/swagger")) h.TryAdd("Content-Security-Policy", "default-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"); return Task.CompletedTask; }); await next(context); } }
